#include <iostream>
#include <queue>
#include <map>
using namespace std;
typedef map<int,int> mi;

mi network_graph[7000];
char maze_grid[20][20];
int rows, cols, total_nodes, parent_array[7000], flow_array[7000], target_dist[10][10];

int compute_flow(int s, int t, int cap){
  int total_flow=0;
  for (int iter=1; iter--;){
    for (int i=total_nodes; i--;) parent_array[i]=-1;
    parent_array[s]=s;
    flow_array[s]=cap;
    queue<int> q;
    q.push(s);
    while (!q.empty()){
      int u=q.front(); q.pop();
      if (u==t){
        for (int v=u; v!=s; v=parent_array[v]){
          network_graph[parent_array[v]][v]-=flow_array[t];
          network_graph[v][parent_array[v]]+=flow_array[t];
        }
        total_flow+=flow_array[t];
        break;
      }
      for (auto it=network_graph[u].begin(); it!=network_graph[u].end(); it++){
        if (it->second>=cap && parent_array[it->first]==-1){
          parent_array[it->first]=u;
          flow_array[it->first]=min(it->second,flow_array[u]);
          q.push(it->first);
        }
      }
    }
  }
  return total_flow;
}

int encode_node(int x,int y,int t){
  return x+y*rows+t*rows*rows+2;
}

int main(){
  ios::sync_with_stdio(false);
  cin>>rows>>cols;

  int total_res=0;
  for (int i=0; i<rows; i++){
    for (int j=0; j<rows; j++){
      cin>>maze_grid[i][j];
      if (maze_grid[i][j]>'0' && maze_grid[i][j]<='9') network_graph[0][encode_node(i,j,0)]=maze_grid[i][j]-'0';
    }
  }
  for (int i=0; i<rows; i++) cin>>maze_grid[i];

  static const int dx[]={-1,0,1,0};
  static const int dy[]={0,-1,0,1};

  queue<pair<int,int>> q_bfs;
  for (int i=rows-1; i>=0; i--){
    for (int j=rows-1; j>=0; j--){
      if (maze_grid[i][j]=='Z') target_dist[i][j]=0, q_bfs.emplace(i,j);
      else target_dist[i][j]=cols+1;
    }
  }

  while (!q_bfs.empty()){
    auto p=q_bfs.front(); q_bfs.pop();
    int i=p.first, j=p.second;
    for (int dir=0; dir<4; dir++){
      int t=target_dist[i][j];
      int x=i+dx[dir], y=j+dy[dir];
      if (x>=0 && y>=0 && x<rows && y<rows && maze_grid[x][y]!='Y' && t+1<target_dist[x][y]){
        target_dist[x][y]=t+1;
        q_bfs.emplace(x,y);
      }
    }
  }

  total_nodes=encode_node(rows-1,rows-1,cols)+1;

  for (int i=0; i<rows; i++){
    for (int j=0; j<rows; j++){
      for (int t=0; t<cols; t++){
        if (t<cols) for (int q=0; q<4; q++){
          int x=i+dx[q], y=j+dy[q];
          if (x>=0 && y>=0 && x<rows && y<rows && maze_grid[x][y]!='Y' && t+1<target_dist[x][y]+(maze_grid[x][y]>'0' && maze_grid[x][y]<='9') && t<target_dist[i][j]){
            network_graph[encode_node(i,j,t)][encode_node(x,y,t+1)]=1000;
          }
        }
        if (maze_grid[i][j]>'0' && maze_grid[i][j]<='9'){
          network_graph[encode_node(i,j,t)][encode_node(i,j,cols)]=maze_grid[i][j]-'0';
        }
      }
      if (maze_grid[i][j]>'0' && maze_grid[i][j]<='9'){
        network_graph[encode_node(i,j,cols)][1]=maze_grid[i][j]-'0';
      }
    }
  }

  for (int u=8; u; u/=2) total_res+=compute_flow(0,1,u);
  cout<<total_res<<'\n';
}
